CREATE TABLE commerce_promotions(id UUID PRIMARY KEY,partner_id VARCHAR(255),code VARCHAR(100) NOT NULL,name VARCHAR(255) NOT NULL,description TEXT,discount_type VARCHAR(40) NOT NULL,discount_value NUMERIC(19,4) NOT NULL,maximum_discount NUMERIC(19,4),minimum_order_amount NUMERIC(19,4) NOT NULL DEFAULT 0,usage_limit BIGINT,usage_limit_per_user BIGINT,usage_count BIGINT NOT NULL DEFAULT 0,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,applicable_product_types TEXT,applicable_entity_ids TEXT,status VARCHAR(30) NOT NULL,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE UNIQUE INDEX uk_commerce_promotion_code ON commerce_promotions(UPPER(code));
CREATE TABLE commerce_commission_rules(id UUID PRIMARY KEY,partner_id VARCHAR(255),product_type VARCHAR(50) NOT NULL,percentage NUMERIC(9,4) NOT NULL DEFAULT 0,fixed_amount NUMERIC(19,4) NOT NULL DEFAULT 0,maximum_amount NUMERIC(19,4),currency VARCHAR(3) NOT NULL,rule_version INTEGER NOT NULL,effective_from TIMESTAMPTZ NOT NULL,effective_until TIMESTAMPTZ,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE commerce_orders(id UUID PRIMARY KEY,reference VARCHAR(60) NOT NULL UNIQUE,idempotency_key VARCHAR(255) NOT NULL UNIQUE,user_id VARCHAR(255) NOT NULL,partner_id VARCHAR(255) NOT NULL,source_entity_id VARCHAR(255) NOT NULL,product_type VARCHAR(50) NOT NULL,status VARCHAR(40) NOT NULL,subtotal NUMERIC(19,4) NOT NULL,discount_amount NUMERIC(19,4) NOT NULL,tax_amount NUMERIC(19,4) NOT NULL,service_fee NUMERIC(19,4) NOT NULL,commission_amount NUMERIC(19,4) NOT NULL,total_amount NUMERIC(19,4) NOT NULL,partner_net_amount NUMERIC(19,4) NOT NULL,currency VARCHAR(3) NOT NULL,promotion_id UUID,pricing_rule_version INTEGER NOT NULL,commission_rule_version INTEGER,payment_id VARCHAR(255),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,paid_at TIMESTAMPTZ);
CREATE INDEX idx_commerce_orders_user ON commerce_orders(user_id,created_at DESC);
CREATE TABLE commerce_order_lines(id UUID PRIMARY KEY,order_id UUID NOT NULL REFERENCES commerce_orders(id),product_id VARCHAR(255) NOT NULL,description VARCHAR(500) NOT NULL,quantity INTEGER NOT NULL,unit_price NUMERIC(19,4) NOT NULL,line_total NUMERIC(19,4) NOT NULL,price_snapshot TEXT NOT NULL);
CREATE TABLE commerce_promotion_usages(id UUID PRIMARY KEY,promotion_id UUID NOT NULL REFERENCES commerce_promotions(id),order_id UUID NOT NULL REFERENCES commerce_orders(id),user_id VARCHAR(255) NOT NULL,used_at TIMESTAMPTZ NOT NULL,UNIQUE(promotion_id,order_id));
CREATE TABLE commerce_ledger(id UUID PRIMARY KEY,partner_id VARCHAR(255) NOT NULL,order_id UUID,transaction_type VARCHAR(40) NOT NULL,amount NUMERIC(19,4) NOT NULL,currency VARCHAR(3) NOT NULL,reference VARCHAR(255) NOT NULL,idempotency_key VARCHAR(255) NOT NULL UNIQUE,occurred_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(255) NOT NULL,reason TEXT);
CREATE INDEX idx_commerce_ledger_partner ON commerce_ledger(partner_id,occurred_at);
CREATE TABLE commerce_refunds(id UUID PRIMARY KEY,order_id UUID NOT NULL REFERENCES commerce_orders(id),amount NUMERIC(19,4) NOT NULL,status VARCHAR(30) NOT NULL,idempotency_key VARCHAR(255) NOT NULL UNIQUE,payment_refund_id VARCHAR(255),reason TEXT,created_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ);
CREATE TABLE commerce_outbox(id UUID PRIMARY KEY,target_topic VARCHAR(120) NOT NULL,event_type VARCHAR(120) NOT NULL,aggregate_id VARCHAR(255) NOT NULL,correlation_id VARCHAR(255),payload TEXT NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE TABLE commerce_processed_events(event_id VARCHAR(255) PRIMARY KEY,event_type VARCHAR(120) NOT NULL,processed_at TIMESTAMPTZ NOT NULL);
